import {catalog} from './media-catalog.mjs?v=4';
export const normalizeName=value=>String(value).normalize('NFKD').replace(/[’‘]/g,"'").toLowerCase().replace(/[^a-z0-9]/g,'');
const aliases={artifacts:{vv:'Viridescent Venerer',viridescent:'Viridescent Venerer',tenacity:'Tenacity of the Millelith','cinder city':'Scroll of the Hero of Cinder City',cindercity:'Scroll of the Hero of Cinder City',disenchantment:'Disenchantment in Deep Shadow',noblesse:'Noblesse Oblige'},characters:{mizuki:'Yumemizuki Mizuki',cryomc:'Aether',cryotraveler:'Aether',traveler:'Aether',traveller:'Aether'},weapons:{sacfrag:'Sacrificial Fragments',sacfrags:'Sacrificial Fragments',sf:'Sacrificial Fragments',echoes:'Echoes of the Heart',exaiphanes:'Exaiphanes Blade',favbow:'Favonius Warbow',favwarbow:'Favonius Warbow',favsword:'Favonius Sword',favlance:'Favonius Lance',favcodex:'Favonius Codex',atonement:'Blade of Atonement',aquila:'Aquila Favonia',tt:'Thrilling Tales of Dragon Slayers',ttds:'Thrilling Tales of Dragon Slayers'}};
export function resolveName(kind,name){return aliases[kind]?.[normalizeName(name)]||String(name).trim().replace(/[’‘]/g,"'")}
const records=new Map(catalog.map(r=>[r.kind+':'+normalizeName(r.name),r]));
const pending=new Map();
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key=(kind,name)=>kind+':'+normalizeName(resolveName(kind,name));
export const findMedia=(kind,name)=>records.get(key(kind,name));
export function mediaMarkup(kind,name,variant=''){const r=findMedia(kind,name);return `<span class="game-art ${kind==='characters'?'character-art':'weapon-art'} ${variant}" data-art-kind="${kind}" data-art-name="${esc(name)}"><span class="art-fallback" ${r?.image?'hidden':''}>${kind==='characters'?'✧':'◇'}<small>${r?.image?'Image unavailable':r?'No image':'Loading art…'}</small></span>${r?.image?`<img src="${esc(r.image)}" alt="${esc(name)} ${kind==='characters'?'portrait':kind==='artifacts'?'artifact set icon':'weapon icon'}" width="128" height="128" decoding="async">`:''}</span>`}
function allowedImage(url){try{const u=new URL(url);return u.protocol==='https:'&&['upload-os-bbs.mihoyo.com','act-webstatic.hoyoverse.com','bbs.hoyolab.com','upload-static.hoyoverse.com'].includes(u.hostname)}catch{return false}}
async function lookup(kind,name){const query=resolveName(kind,name),k=key(kind,name);if(records.has(k))return records.get(k);if(pending.has(k))return pending.get(k);const task=(async()=>{try{const response=await fetch(`https://genshin-db-api.vercel.app/api/v5/${kind}?query=${encodeURIComponent(query)}&matchCategories=false`,{signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error('API unavailable');const raw=await response.text(),data=raw?JSON.parse(raw):null;if(!data||Array.isArray(data)||normalizeName(data.name)!==normalizeName(query)){const missing={name:query,image:null};records.set(k,missing);return missing}const url=[data.images?.mihoyo_flower,data.images?.mihoyo_icon,data.images?.hoyowiki_icon,data.images?.icon].find(allowedImage);const r={name:data.name,id:data.id,image:url||null,rarity:data.rarity};records.set(k,r);return r}catch{return {name:query,image:null,temporary:true}}})();pending.set(k,task);try{return await task}finally{pending.delete(k)}}
export async function hydrateMedia(){await Promise.all(Array.from(document.querySelectorAll('[data-art-kind]')).map(async el=>{if(el.querySelector('img'))return;const r=await lookup(el.dataset.artKind,el.dataset.artName);if(!el.isConnected)return;const fallback=el.querySelector('.art-fallback');if(r.image){const img=document.createElement('img');img.alt=el.dataset.artName+(el.dataset.artKind==='characters'?' portrait':el.dataset.artKind==='artifacts'?' artifact set icon':' weapon icon');img.width=128;img.height=128;img.decoding='async';img.src=r.image;fallback.hidden=true;el.append(img)}else{fallback.hidden=false;fallback.querySelector('small').textContent=r.temporary?'Art unavailable':'No matching artwork';el.title=r.temporary?'Image lookup failed. Reload to retry.':'No exact API name match. Check the character or weapon name.'}}))}
document.addEventListener('error',event=>{const img=event.target;if(!(img instanceof HTMLImageElement)||!img.closest('.game-art'))return;const fallback=img.parentElement.querySelector('.art-fallback');fallback.hidden=false;fallback.querySelector('small').textContent='Image unavailable';img.remove()},true);
